package com.earthtrip.expense.adapter.in.web.api.v1.trips.by_trip_id.exchange_rate_snapshots;import com.earthtrip.expense.application.port.in.FinanceLedgerUseCase;import com.earthtrip.sharedkernel.security.CurrentActor;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import java.math.BigDecimal;import java.time.Instant;import java.util.*;import org.springframework.http.HttpStatus;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/trips/{tripId}/exchange-rate-snapshots") class ExchangeRateSnapshotsController{private final FinanceLedgerUseCase useCase;private final CurrentActor actor;ExchangeRateSnapshotsController(FinanceLedgerUseCase u,CurrentActor a){useCase=u;actor=a;}@GetMapping List<FinanceLedgerUseCase.RateResult> get(@PathVariable UUID tripId){return useCase.rates(tripId,actor.requireUserId());}@PostMapping @ResponseStatus(HttpStatus.CREATED) FinanceLedgerUseCase.RateResult post(@PathVariable UUID tripId,@Valid @RequestBody RateMutation r){return useCase.createRate(tripId,actor.requireUserId(),new FinanceLedgerUseCase.RateCommand(r.requestId(),r.baseCurrency(),r.quoteCurrency(),r.rate(),r.source(),r.observedAt()));}}
record RateMutation(@NotNull UUID requestId,@NotBlank String baseCurrency,@NotBlank String quoteCurrency,@NotNull @DecimalMin(value="0",inclusive=false)BigDecimal rate,String source,@NotNull Instant observedAt){}
